package bmmgen

import (
	"bytes"
	"fmt"
)

// walkerPolymorphicFile is the generated file of internal/rmjsonwalk, the
// walker the canonical-JSON options for unmatched members use (REQ-170).
const walkerPolymorphicFile = "polymorphic_gen.go"

// walkerRMImport is the import path of the RM package, which the walker's
// generated table names its interfaces through.
const walkerRMImport = "github.com/cadasto/openehr-sdk-go/openehr/rm"

// RenderWalkerPolymorphicFile renders internal/rmjsonwalk/polymorphic_gen.go
// for the RM target: polymorphicClass, a type switch over a pointer to each
// polymorphic RM interface that has a decode hook, naming the BMM class the
// interface stands for and the class an elided `_type` falls back to. The
// walker reads a decode target's Go type with it (REQ-170) without reflecting
// over the registry (REQ-024), and the table stays off the public API.
//
// Returns (nil, nil) for any other target: the JSON walk checks RM classes
// only.
func RenderWalkerPolymorphicFile(plan *Plan) ([]byte, error) {
	if plan.Target.GoPackage != "rm" {
		return nil, nil
	}
	ifaces, err := polymorphicInterfaces(plan)
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by bmmgen; DO NOT EDIT.\n")
	b.WriteString("// Source: " + plan.Target.SourceLabel + "\n\n")
	b.WriteString("package rmjsonwalk\n\n")
	fmt.Fprintf(&b, "import %q\n\n", walkerRMImport)
	b.WriteString("// polymorphicClass reports the BMM classes behind the polymorphic RM\n")
	b.WriteString("// interface p points to, such as a *rm.DataValue. class is the class the\n")
	b.WriteString("// interface stands for: an abstract class, or for a narrow interface\n")
	b.WriteString("// (<Parent>Like) its parent class. fallback is the class a value that\n")
	b.WriteString("// leaves out `_type` decodes as, which is the parent class of a narrow\n")
	b.WriteString("// interface; it is empty where the decoder refuses such a value. ok is false\n")
	b.WriteString("// when p points to no polymorphic RM interface with a decode hook.\n")
	b.WriteString("func polymorphicClass(p any) (class, fallback string, ok bool) {\n")
	b.WriteString("\tswitch p.(type) {\n")
	for _, pi := range ifaces {
		fallback := ""
		if pi.Narrow {
			fallback = pi.Class
		}
		fmt.Fprintf(&b, "\tcase *rm.%s:\n\t\treturn %q, %q, true\n", pi.GoName, pi.Class, fallback)
	}
	b.WriteString("\t}\n")
	b.WriteString("\treturn \"\", \"\", false\n")
	b.WriteString("}\n")
	return formatGenerated(b.Bytes(), walkerPolymorphicFile)
}
